{
  "interpretation": {
    "name": "TightenF25AtStation1WithNR7",
    "scope": {"line": 1, "station": "st1", "tool": "NR7", "variant": "F25"},
    "goal": "Bring NR7 from the crib to station st1, tighten the fasteners of the upcoming F25 according to its MES program, evaluate and record the result, then return NR7 to the crib and release the reservation.",
    "constraints": [
      "NR7 must be reserved before any use and the reservation token must be used by every tool-using Step",
      "NR7 must be at the station before configure-tool and tighten-fasteners",
      "The tightening program must come from get-program, with no literal torque or tolerance values in the Recipe",
      "The tightening result must be evaluated and recorded",
      "NR7 must be returned to the crib and the reservation released so other requesters are not blocked",
      "transport-tool Steps must be delegated to agvexecutor"
    ],
    "preference": "Release the tool as soon as it is back in the crib.",
    "priority": "normal",
    "horizon": "Next F25 arriving at station st1 on line 1 (single execution)",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "tighten-f25-line1-nr7",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
